arguments.command:
cat > src/CheckoutPricing.Application/CheckoutCalculator.cs <<'E'
namespace CheckoutPricing.Application;

public sealed class CheckoutCalculator
{
    // No pricing rules exist yet, so the payable total equals the subtotal.
    public decimal CalculatePayableTotal(string customerTier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/GoldDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public class GoldDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        var total = new CheckoutCalculator().CalculatePayableTotal("Gold", 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Expected|Actual|Passed!|Failed!" | head

